<script lang="ts">
 import type { ParkFilters } from '../types/park'; import { activeFilterCount,defaultFilters } from '../lib/filterParks';
 let {filters=$bindable(),resultCount,open,onClose}:{filters:ParkFilters;resultCount:number;open:boolean;onClose:()=>void}=$props();
 const groups={facilities:[['bench','Bench'],['toilet','Toilet'],['waterTapAccess','Water tap access'],['playground','Playground'],['publicSportPark','Public sport park'],['footballSportCourts','Football & sport courts'],['dogOffLeashArea','Dog off-leash area']],access:[['wheelchairAccessible','Wheelchair accessible'],['crossings','Crossings'],['trafficLight','Traffic light']],safety:[['streetParkLight','Street / Park light'],['fencedArea','Fenced area']]} as const;
</script>
{#if open}<button class="scrim" aria-label="Close filters" onclick={onClose}></button>{/if}<aside class:open aria-label="Park filters"><div class="filter-head"><div><p class="eyebrow">Refine your search</p><h2>What matters to you?</h2></div><button class="close" onclick={onClose} aria-label="Close filters">×</button></div><div class="result-row"><strong>{resultCount} parks</strong><span>match your needs</span></div><form class="filter-form"><details open><summary>Facilities & Recreation</summary><fieldset>{#each groups.facilities as item}<label class="check"><input type="checkbox" bind:checked={filters[item[0]]}/><span>{item[1]}</span></label>{/each}</fieldset></details><details open><summary>Greenery</summary><fieldset>{#each [['canopyCover','Canopy cover'],['grassCover','Grass cover']] as group}<div class="radio-group"><span>{group[1]}</span><div class="segments">{#each ['any','low','mid','high'] as option}<label><input type="radio" name={group[0]} value={option} bind:group={filters[group[0] as 'canopyCover'|'grassCover']}/><span>{option[0].toUpperCase()+option.slice(1)}</span></label>{/each}</div></div>{/each}</fieldset></details><details open><summary>Accessibility & Access</summary><fieldset>{#each groups.access as item}<label class="check"><input type="checkbox" bind:checked={filters[item[0]]}/><span>{item[1]}</span></label>{/each}<div class="radio-group"><span>Opening hours / Public access</span><div class="segments three">{#each [['any','Any'],['anytime','Anytime'],['restricted','Restricted']] as option}<label><input type="radio" name="access" value={option[0]} bind:group={filters.publicAccess}/><span>{option[1]}</span></label>{/each}</div></div></fieldset></details><details open><summary>Safety & Infrastructure</summary><fieldset>{#each groups.safety as item}<label class="check"><input type="checkbox" bind:checked={filters[item[0]]}/><span>{item[1]}</span></label>{/each}</fieldset></details></form><button class="clear" onclick={()=>filters={...defaultFilters}} disabled={activeFilterCount(filters)===0}>Clear all filters</button></aside>
